G=[['拉丁语 grandis','大的、成长充分的；更早来源未定']]
GRAND=G+[['古法语 grant / grand → 英语 grand','大、重要 → 宏伟、盛大、出色']]
GF=GRAND+[['中古英语 grand- + father → grandfather','仿法语亲属命名模式：父母的父亲']]
GM=GRAND+[['中古英语 grand- + mother → grandmother','仿法语亲属命名模式：父母的母亲']]
GIOSE=G+[['意大利语 grandioso → 法语 grandiose → 英语 grandiose','宏大、壮丽 → 常指宏伟得过头、夸张']]
GSTAND=GRAND+[['英语 grand + stand → grandstand〔名词〕','主要、大型的看台'],['grandstand player 一类说法 → grandstand〔动词〕','为看台观众卖弄 → 哗众取宠']]
W=[
E('grand','/ɡrænd/','宏伟的；盛大的；重要的；很好的；一千元〔口语名词〕','不只是尺寸大，还带着气派、隆重、让人觉得重要的感觉。','借自法语 grand、grant，接拉丁 grandis；较远来源不确定，不按英语 gran- 与 -d 拆。',GRAND,'a grand building 很有气势；a grand opening 是隆重开幕。口语 That’s grand 可表示很好。three grand 常指三千元，币种依语境；grand piano 是三角钢琴这个固定名称。','a grand entrance；a grand opening；the grand total；three grand。','big 主要说大；grand 往往多出气派、重要或隆重。grandiose 则常批评气派得过头。',('The hotel has a grand entrance with marble columns.','酒店有一座带大理石柱的气派入口。'),('The grand total comes to eighty pounds.','总金额为八十英镑。'),('The repairs cost about two grand.','修理费大约两千元。'),sources=['https://www.etymonline.com/word/grand','https://www.oxfordlearnersdictionaries.com/definition/english/grand_1']),
E('grandly','/ˈɡrændli/','气派地；郑重而自信地；摆架子地','动作或说话姿态做得很大，可能让人佩服，也可能有点端着。','grand + -ly；把宏伟、隆重或自命不凡的性质转成做事方式。',GRAND+[['英语 grand + -ly → grandly','宏伟、气派的 → 气派地、郑重其事地']],'announce grandly 可以是真有气势，也可以是一本正经说大话；grandly decorated 则侧重华丽布置。语气靠上下文判断。','announce grandly；gesture grandly；grandly decorated。','proudly 强调自豪；grandly 更像把姿态、排场或口气放大。',('He grandly announced that dinner was on him.','他豪气地宣布晚饭由他请客。'),('The ballroom was grandly decorated for the anniversary.','舞厅为周年庆典布置得十分气派。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/grandly','https://en.wiktionary.org/wiki/grandly#English']),
E('grandfather','英 /ˈɡræn(d)fɑːðə/；美 /ˈɡræn(d)fɑːðər/','祖父；外祖父；保留旧待遇〔动词〕','沿着父母这一层再往上一层的男性长辈，英语不在这个词里区分爸爸一边和妈妈一边。','grand- + father，中古英语已有，可能仿法语 grand-père；现代动词来自 grandfather clause 的旧待遇保留用法。',GF+[['英语 grandfather clause → grandfather〔动词〕','保留某些旧条件、旧资格的适用方式']],'maternal grandfather 是外祖父，paternal grandfather 是祖父。合同或软件中 grandfather existing users 指让现有用户保留旧条件；该用法源自美国祖父条款，早期条款曾用于维持白人选举资格、排斥黑人选民。','my grandfather；maternal grandfather；grandfather existing users。','grandfather 是较完整、中性的称呼；grandpa、granddad 更亲近口语。动词义不表示把人变成祖父。',('My grandfather taught me how to repair a bicycle.','祖父教过我怎样修自行车。'),('Existing subscribers will be grandfathered into the old pricing plan.','现有订阅者将继续沿用旧价格方案。'),sources=['https://www.etymonline.com/word/grandfather','https://www.merriam-webster.com/dictionary/grandfather']),
E('grandmother','英 /ˈɡræn(d)mʌðə/；美 /ˈɡræn(d)mʌðər/','祖母；外祖母','父亲或母亲的母亲；具体是哪一边，要靠上下文或额外说明。','grand- + mother，中古英语形成，可能仿法语 grand-mère；不是单纯表示年龄大的任何母亲。',GM,'maternal grandmother 是外祖母，paternal grandmother 是祖母。谈自己的家庭关系通常用 my grandmother；直接称呼时也可以大写 Grandmother，但比 Grandma 正式。','my grandmother；maternal grandmother；paternal grandmother。','grandmother 不区分奶奶与外婆；中文翻译应根据家族关系选择，不能凭英文词形判断。',('My grandmother keeps a small garden behind her house.','祖母在屋后打理着一个小花园。'),('Her maternal grandmother grew up near the coast.','她的外祖母在海边长大。'),sources=['https://www.etymonline.com/word/grandmother','https://www.oxfordlearnersdictionaries.com/definition/english/grandmother']),
E('grandparent','英 /ˈɡræn(d)peərənt/；美 /ˈɡræn(d)perənt/','祖父母或外祖父母中的一人；祖辈','不先指定男性女性、父系母系，只说父母上一辈的亲人。','grand- + parent；与 grandfather、grandmother 同属英语亲属关系构词。',GRAND+[['英语 grand- + parent → grandparent','比父母再上一代的父母']],'单数 one grandparent 是一位祖辈，复数 grandparents 常统称祖父母或外祖父母。它不必只指某一对夫妻，要看所指家庭范围。','a grandparent；grandparents and grandchildren；visit one’s grandparents。','ancestor 包括更早许多代祖先；grandparent 明确只在父母之上一代。',('Each child was invited to bring a grandparent to the event.','每个孩子都可以邀请一位祖辈参加活动。'),('Her grandparents live in different cities.','她的祖辈住在不同的城市。'),sources=['https://www.etymonline.com/word/grandparent','https://www.oxfordlearnersdictionaries.com/definition/english/grandparent']),
E('grandchild','/ˈɡræn(d)tʃaɪld/','孙子女；外孙子女中的一人','从自己往下数：先是孩子，再是孩子的孩子。','grand- + child；复数是 grandchildren，保留 child → children 的不规则变化。',GRAND+[['英语 grand- + child → grandchild','与自己隔一代的孩子']],'grandchild 不标明性别，也不区分儿子还是女儿所生。one grandchild、three grandchildren 的单复数需要特别注意。','a first grandchild；young grandchildren；spend time with grandchildren。','grandson、granddaughter 分别说明男性、女性；grandchild 可以统称，也可指尚未说明性别的一人。',('They welcomed their first grandchild in June.','他们在六月迎来了第一个孙辈。'),('She reads stories to her grandchildren every weekend.','她每个周末都给孙辈们讲故事。'),sources=['https://www.etymonline.com/word/grandchild','https://www.oxfordlearnersdictionaries.com/definition/english/grandchild']),
E('grandson','/ˈɡræn(d)sʌn/','孙子；外孙','儿子或女儿的儿子；从祖辈的视角来称呼这个男孩或成年男性。','grand- + son；grand- 在这里说明亲属间隔，不是在夸孩子多伟大。',GRAND+[['英语 grand- + son → grandson','子女的儿子']],'my grandson 可以是小孩，也可以已经成年；词义标的是关系，不是年龄。需要区分父系、母系时，句子要另作说明。','my eldest grandson；a young grandson；grandsons and granddaughters。','nephew 是兄弟姐妹的儿子，grandson 是自己孩子的儿子，家谱路径不同。',('Her grandson has just started university.','她的孙子刚开始读大学。'),('He took his grandson to the science museum.','他带孙子去了科学博物馆。'),sources=['https://www.etymonline.com/word/grandson','https://www.oxfordlearnersdictionaries.com/definition/english/grandson']),
E('granddaughter','英 /ˈɡræn(d)dɔːtə/；美 /ˈɡræn(d)dɔːtər/','孙女；外孙女','儿子或女儿的女儿，同样不在英语词里区分父系与母系。','grand- + daughter；拼写中保留相邻的两个 d，口语不必把它们读成两个分开的停顿。',GRAND+[['英语 grand- + daughter → granddaughter','孩子的女儿 → 孙女、外孙女']],'a granddaughter 可以已成年；granddaughters 的复数直接加 -s，不像 grandchild 要变 children。','my granddaughter；an eldest granddaughter；two granddaughters。','daughter 是女儿；granddaughter 是下一代的女儿，关系再隔一层。',('Their granddaughter sent them a postcard from abroad.','他们的孙女从国外寄来了一张明信片。'),('She keeps a photograph of her two granddaughters on her desk.','她在桌上放着两个孙女的合影。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/granddaughter','https://en.wiktionary.org/wiki/granddaughter#English']),
E('grandma','/ˈɡrænmɑː/，亦 /ˈɡrænmə/','奶奶；外婆；祖母的亲昵称呼','家里亲切地叫祖母或外祖母，就像直接叫“奶奶、外婆”。','grand- + ma，仿 grandmother 缩短成亲昵称呼；ma 本身是 mother 的口语称呼。',GM+[['英语 grand- + ma → grandma','祖母、外祖母的亲昵称呼']],'说 my grandma 时是普通名词；直接称呼 Grandma 时常大写。这个词不表示她一定属于爸爸那边。','my grandma；Grandma’s house；visit Grandma。','grandmother 比较完整、中性；grandma 更亲密日常。granny 是另一个常见亲昵称呼。',('My grandma makes excellent soup.','我奶奶做的汤很好喝。'),('Grandma, would you like a cup of tea?','奶奶，您想喝杯茶吗？'),sources=['https://www.etymonline.com/word/grandma','https://www.oxfordlearnersdictionaries.com/definition/english/grandma']),
E('grandpa','/ˈɡrænpɑː/，口语常 /ˈɡræmpɑː/','爷爷；外公；祖父的亲昵称呼','和家里祖父辈男性说话时，比 grandfather 更亲近的称呼。','grand- + pa，仿 grandfather；pa 是 father 的口语称呼，相邻 n、p 在口语中常同化。',GF[:3]+[['英语 grand- + pa → grandpa','祖父、外祖父的亲昵称呼']],'Grandpa can help 是直接把家里这个称呼当名称；my grandpa 是向别人谈自己的祖父或外祖父。不要把 grand- 发成另一个独立重读词。','my grandpa；Grandpa’s stories；ask Grandpa。','grandpa、granddad 都亲切口语；grandfather 在正式家族介绍中更常见。',('Grandpa showed us his old camera.','爷爷给我们看了他的旧相机。'),('We called my grandpa on his birthday.','爷爷生日那天，我们给他打了电话。'),sources=['https://www.etymonline.com/word/grandpa','https://www.oxfordlearnersdictionaries.com/definition/english/grandpa']),
E('granddad','/ˈɡrændæd/','爷爷；外公','把祖父或外祖父当家里熟悉亲近的人来叫。','grand- + dad；也写 grandad。dad 是父亲的口语称呼，组合后关系上移一代。',GF[:3]+[['英语 grand- + dad → granddad / grandad','祖父、外祖父的口语称呼']],'可用作普通名词 my granddad，也可大写作为直接称呼。两种常见拼写 granddad、grandad 不对应不同亲属关系。','my granddad；Granddad’s garden；visit Granddad。','dad 是爸爸；granddad 是父母的爸爸。词尾都亲切，但辈分不同。',('My granddad still rides his bicycle every morning.','我爷爷仍然每天早晨骑自行车。'),('Granddad, tell us about your first job.','爷爷，给我们讲讲您的第一份工作吧。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/grandad','https://en.wiktionary.org/wiki/granddad#English']),
E('granddaddy','/ˈɡrændædi/','爷爷、外公；鼻祖；最老资格或最突出的事物〔口语〕','先是亲昵的祖父称呼，再把“资历最老的长辈”借来形容某类事物里的老祖宗。','grand- + daddy；从亲属称呼发展出开创者、老资格事物等比喻义。',GF[:3]+[['英语 grand- + daddy → granddaddy','亲昵的祖父称呼 → 某类事物中的鼻祖、老资格者']],'the granddaddy of modern computers 可以说早期先驱；the granddaddy of all problems 有时夸张说一个格外重大的问题。通常口语，不要求准确证明它历史上绝对第一。','the granddaddy of；the granddaddy of them all；my granddaddy。','ancestor 可以正式说祖先；granddaddy 的比喻更口语，常带亲切、夸张或强调资历的味道。',('My granddaddy taught me to recognise birds by their calls.','爷爷教我通过叫声辨认鸟。'),('The museum displays the granddaddy of today’s portable radios.','博物馆展出了现代便携收音机的一位老祖宗。'),sources=['https://www.merriam-webster.com/dictionary/granddaddy','https://www.oxfordlearnersdictionaries.com/definition/english/granddaddy']),
E('grandkid','/ˈɡræn(d)kɪd/','孙子女；外孙子女〔口语〕','聊天时把 grandchild 换成更随意的说法。','grand- + kid“孩子”；在现代英语里以熟悉的亲属构词模式形成。',GRAND+[['英语 grand- + kid → grandkid','孩子的孩子；grandchild 的口语说法']],'常用复数 grandkids 来谈孙辈们。kid 在这里不意味着动物幼崽，而是口语中的孩子。即使孙辈已长大，家人也可能继续这样称呼。','the grandkids；spend time with the grandkids；photos of grandkids。','grandchildren 是中性完整说法；grandkids 更随意，正式表格一般不用它。',('The grandkids are staying with us this weekend.','孙辈们这个周末住在我们家。'),('He proudly showed me photos of his grandkids.','他自豪地给我看孙辈们的照片。'),sources=['https://www.merriam-webster.com/dictionary/grandkid','https://en.wiktionary.org/wiki/grandkid#English']),
E('granny','/ˈɡræni/','奶奶；外婆；老太太〔口语，语气依场合〕','最常见是家里对祖母辈女性的亲昵称呼。','通常解释为 grannam 的缩短、亲昵形式；grannam 又缩自较早 grandam / grandame，而非必须直接从 grandmother 删字母。',G+[['古法语 grand / grant','大；进入亲属复合词'],['英语 grandam / grandame → grannam','祖母；grand- + dame 的旧称'],['grannam → granny / grannie','缩短成亲昵称呼']],'my granny 常有亲近感；直接称陌生老妇人为 granny 却可能显得失礼或轻慢。也见 Granny Smith 这个苹果品种名，但不是所有青苹果都叫这个名字。','my granny；Granny’s house；Granny Smith apples。','grandma 和 granny 意思接近，家里习惯哪种就用哪种；历史缩略路线并不完全一样。',('My granny taught me a few words of her first language.','外婆教过我几句她的母语。'),('We spent the afternoon at Granny’s house.','我们在外婆家度过了下午。'),sources=['https://www.etymonline.com/word/granny','https://www.oxfordlearnersdictionaries.com/definition/english/granny']),
E('grandeur','英 /ˈɡrændʒə/，亦 /ˈɡrændjʊə/；美 /ˈɡrændʒər/','宏伟；壮丽；堂皇气派','看到高山、宫殿或盛典时，那种超出日常尺度的气势。','借自法语 grandeur，接 grand“伟大、宏大”，再接拉丁 grandis；英语不是 grand 加一个普通后缀 -eur。',G+[['古法语 grandur → 法语 grandeur → 英语 grandeur','宏大、伟大的性质 → 壮丽、气派']],'the grandeur of the mountains 是群山的壮丽；faded grandeur 是昔日气派尚存却已衰落的样子。词本身多带赞赏，和 grandiosity 的夸大感不同。','natural grandeur；faded grandeur；the grandeur of a palace。','size 只是大小；grandeur 还包括气势和审美感受。grandiosity 更容易暗示不切实际的自大。',('The photograph captures the grandeur of the mountain range.','照片捕捉到了山脉的壮丽气势。'),('The old theatre retains traces of its former grandeur.','老剧院仍保留着昔日辉煌的痕迹。'),sources=['https://www.etymonline.com/word/grandeur','https://www.oxfordlearnersdictionaries.com/definition/english/grandeur']),
E('grandiose','英 /ˈɡrændiəʊs/；美 /ˈɡrændioʊs/','宏大而夸张的；好大喜功的','蓝图画得极其气派，却让人怀疑是否现实、是否只是摆排场。','经法语 grandiose 借自意大利 grandioso，接拉丁 grandis；不是现代 grand 机械加 -iose。',GIOSE,'grandiose plans 常带不切实际的批评；grandiose architecture 可能说堂皇到夸张。这个词也有宏伟义，但现代阅读中通常先留意它的负面语气。','grandiose plans；a grandiose scheme；grandiose claims。','ambitious 表有雄心，未必不现实；grandiose 往往认为规模、口气或自我评价过大。',('The committee rejected his grandiose plan for a new palace.','委员会否决了他那宏大得不切实际的新宫殿计划。'),('The advertisement made grandiose claims about a simple gadget.','广告把一个普通小工具吹得神乎其神。'),sources=['https://www.etymonline.com/word/grandiose','https://www.oxfordlearnersdictionaries.com/definition/english/grandiose']),
E('grandiosity','英 /ˌɡrændiˈɒsəti/；美 /ˌɡrændiˈɑːsəti/','夸大、浮夸；过高的自我评价','把自己的能力、地位或计划看得特别大，超出了现实能支持的程度。','grandiose + -ity，形成表示性质、倾向的名词；历史上承接宏大、浮夸这条支线。',GIOSE+[['英语 grandiose → grandiosity','宏大、夸张的 → 浮夸与自我夸大的倾向']],'the grandiosity of a plan 指计划的浮夸；a character’s grandiosity 可描述人物自视过高。心理学也使用它，但日常一次说大话不足以作任何诊断。','a sense of grandiosity；the grandiosity of a scheme；confidence and grandiosity。','confidence 是自信；grandiosity 暗示评价膨胀，和现实依据不相称。',('The satire exposes the grandiosity of the ruler’s ambitions.','这部讽刺作品揭露了统治者野心的浮夸。'),('Her confidence never slipped into grandiosity.','她一直自信，却从未变得妄自尊大。'),sources=['https://www.etymonline.com/word/grandiosity','https://www.merriam-webster.com/dictionary/grandiosity']),
E('grandee','/ɡrænˈdiː/','显贵；资深要人；西班牙高等贵族','某个圈子里有地位、有资历，说话很有分量的人。','来自西班牙语 grande，原是“大、重要的”形容词，转指高级贵族；上接拉丁 grandis。',G+[['西班牙语 grande〔形容词转贵族名称〕→ 英语 grandee','大、重要 → 显贵、资深要人']],'a party grandee 常指政党元老；a cultural grandee 可指文化界有威望的人。不是随便一个年龄大的成员，重点在地位与影响力。','a party grandee；political grandees；a Spanish grandee。','veteran 强调经验、资历；grandee 还带有显赫地位或圈内权威的意味。',('Several party grandees attended the ceremony.','几位政党元老出席了典礼。'),('The portrait depicts a Spanish grandee in formal dress.','肖像画描绘了一位身着礼服的西班牙高等贵族。'),sources=['https://www.etymonline.com/word/grandee','https://www.oxfordlearnersdictionaries.com/definition/english/grandee']),
E('grandiloquent','/ɡrænˈdɪləkwənt/','夸夸其谈的；言辞浮夸的','本来几句话能说清，却铺满宏大词语，显得自己很有气势。','远接拉丁 grandis“宏大” + loqui“说话”。近源有法语借入等解释；Etymonline 认为英语可能由更早 grandiloquence 反构。',G+[['拉丁语 grandis + loqui → grandiloquus / grandiloquentia','宏大 + 说话 → 言辞浮夸及其性质'],['法语等借入路线；或英语 grandiloquence 反构 → grandiloquent','具体近源有不同分析，均归宏大言辞支线']],'grandiloquent language 是浮夸辞藻；grandiloquent promises 是说得极漂亮、极宏大的承诺。通常带批评，不能单纯当成“口才好”。','grandiloquent language；a grandiloquent speech；grandiloquent promises。','eloquent 可以是真正有说服力、表达动人；grandiloquent 常说话语铺张，内容未必跟得上。',('The speech was full of grandiloquent promises but few details.','演讲满是浮夸承诺，却少有具体细节。'),('She replaced the grandiloquent opening with a simple explanation.','她把夸夸其谈的开场改成了一段简明解释。'),sources=['https://www.etymonline.com/word/grandiloquent','https://www.merriam-webster.com/dictionary/grandiloquent','https://en.wiktionary.org/wiki/grandiloquent#English']),
E('grandstand','/ˈɡrændstænd/','大看台；哗众取宠、做给观众看〔动词〕','先是看比赛的主要看台，再变成“为了让看台鼓掌而卖弄”。','grand + stand“看台”；动词来自 grandstand player 一类体育用语，指刻意向观众炫技。',GSTAND,'sit in the grandstand 是坐在看台上；a politician is grandstanding 指他在做显眼、讨好观众的表现。动词明显贬义，不只是正常公开发言。','the main grandstand；grandstand for the cameras；political grandstanding。','perform 是表演或履职；grandstand 强调抢眼、求掌声，可能忽略实际任务。',('The crowd filled the grandstand before the race.','比赛开始前，人群就坐满了大看台。'),('He used the meeting to grandstand for the cameras.','他利用会议在镜头前作秀。'),sources=['https://www.etymonline.com/word/grandstand','https://www.oxfordlearnersdictionaries.com/definition/english/grandstand_1']),
E('grandstanding','/ˈɡrændstændɪŋ/','作秀；哗众取宠；卖弄','事情还没真正推进，却忙着让观众看见自己多出色、多坚定。','grandstand + -ing；承接由体育看台衍生的卖弄动词，不是“站得很高”。',GSTAND+[['英语 grandstand → grandstanding','向观众卖弄 → 作秀行为']],'political grandstanding 指政治作秀；accuse someone of grandstanding 是批评其为了博取关注。是否属于作秀是语境中的评价，词本身不是中性活动名称。','political grandstanding；public grandstanding；accuse someone of grandstanding。','publicity 是曝光、宣传；grandstanding 特别批评为吸引掌声而摆姿态。',('The chair asked for practical proposals instead of grandstanding.','主持人要求提出实际建议，别只顾作秀。'),('Her opponents dismissed the announcement as political grandstanding.','她的反对者把这项宣布斥为政治作秀。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/grandstanding','https://www.etymonline.com/word/grandstand']),
]
MO=[['拉丁语 monere → monstrum','提醒、警告 → 被视为征兆的异常现象']]
SHOW=MO+[['拉丁语 monstrare','把东西显示、指给人看']]
DM=SHOW+[['拉丁语 de- + monstrare → demonstrare','加强显示 → 指明、证明']]
DEMSTR=DM+[['拉丁语 demonstratus → 英语 demonstrate','指明的分词形式 → 展示、证明；后来也指公开示威']]
DEMATION=DM+[['拉丁语 demonstratio → 古法语 demonstration / 英语 demonstration','证明、指明 → 演示；公开表达诉求的活动']]
DEMABLE=DM+[['拉丁语 demonstrabilis → 古法语 demonstrable / 英语 demonstrable','能够显示、证明的']]
DEMATIVE=DM+[['拉丁语 demonstrativus → 法语 démonstratif → 英语 demonstrative','显示、指明的 → 感情外露的；语法中指示的']]
MONSTROUS=MO+[['拉丁语 monstruosus / monstrosus → 法语 monstruos 等','异常、令人惊骇的'],['英语 monstruous → monstrous','像怪物般的；巨大、恶劣到惊人的']]
REM=SHOW+[['中世纪拉丁语 re- + monstrare → remonstrare','再或加强显示 → 让人看清、提出理由']]
W += [
E('monster','英 /ˈmɒnstə/；美 /ˈmɑːnstər/','怪物；残暴的人；巨大、难对付的东西','童话里可能是长着怪异身体的生物，现实比喻则常是可怕的人或难以控制的大东西。','经古法语 monstre 接拉丁 monstrum“征兆、异常现象”，与 monere“提醒、警告”相连；源头不是英语 mon- 加 -ster。',MO+[['古法语 monstre → 英语 monster','古人视为征兆的异常事物 → 想象中的怪物、残暴者、庞然大物']],'a sea monster 是海怪；a monster of a machine 是巨大机器；create a monster 可说自己造成了难以控制的问题。旧词源反映古人的信念，不代表异常外表能说明一个人的品格。','a sea monster；a monster of a machine；create a monster。','creature 是生物或虚构生物的中性词；monster 通常带恐惧、巨大或邪恶的色彩。',('A friendly monster appears in the children’s story.','这个儿童故事里出现了一只友善的怪物。'),('The tiny project grew into an administrative monster.','那个小项目发展成了难以驾驭的行政巨物。'),sources=['https://www.etymonline.com/word/monster','https://www.oxfordlearnersdictionaries.com/definition/english/monster']),
E('monstrous','英 /ˈmɒnstrəs/；美 /ˈmɑːnstrəs/','巨大的；骇人的；极其恶劣的','大得、怪得或坏得让人觉得不像寻常事物。','经法语或直接由拉丁 monstruosus、monstrosus 借入，英语旧形有 monstruous；现代联系 monster + -ous，但历史并非只从英语名词新造。',MONSTROUS,'a monstrous building 可以是巨大得压迫人的建筑；a monstrous lie 是极其可恶的谎话。它既能评价尺寸，也能评价行为，不能每处都译成“怪物的”。','a monstrous lie；a monstrous injustice；a monstrous structure。','huge 只说明巨大；monstrous 往往还带震惊、反感或不合常理的判断。',('A monstrous tower blocked the view of the hills.','一座庞大的高塔挡住了山景。'),('The verdict was described as a monstrous injustice.','那项判决被形容为极其骇人的不公。'),sources=['https://www.etymonline.com/word/monstrous','https://www.oxfordlearnersdictionaries.com/definition/english/monstrous']),
E('monstrously','英 /ˈmɒnstrəsli/；美 /ˈmɑːnstrəsli/','极其；骇人地；残酷恶劣地','把程度推到令人吃惊、觉得过分的位置。','monstrous + -ly；沿用巨大、骇人或恶劣的几个形容词方向。',MONSTROUS+[['英语 monstrous + -ly → monstrously','巨大、恶劣的 → 极其、恶劣地']],'monstrously unfair 是极其不公；monstrously expensive 是贵得离谱。它比 very 情绪更强，常含说话人的反感。','monstrously unfair；monstrously expensive；behave monstrously。','extremely 可以中性加强程度；monstrously 经常带“太过分、让人难以接受”的态度。',('The fee seemed monstrously high for such a simple service.','这么简单的服务却收这么高的费用，显得贵得离谱。'),('They had been treated monstrously unfairly.','他们遭到了极其不公平的对待。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/monstrously','https://en.wiktionary.org/wiki/monstrously#English']),
E('monstrosity','英 /mɒnˈstrɒsəti/；美 /mɑːnˈstrɑːsəti/','丑陋庞大的东西；怪异之物；可憎事物','看着某个庞大、难看或失去比例的东西，觉得“这到底是什么怪东西”。','晚期拉丁 monstrositas、monstruositas 经法语等进入英语；现代可与 monstrous + -ity 对照，但名词有独立借入历史。',MO+[['拉丁语 monstrosus / monstruosus → 晚期拉丁语 monstrositas 等','怪异的 → 怪异性质、异常之物'],['法语 monstruosité / 拉丁语 → 英语 monstrosity','怪异之物；难看庞大的东西']],'an architectural monstrosity 是强烈贬低某座建筑难看或失调。它不是客观测量标准，而是说话人的负面评价；现代也不宜拿它中性称呼有身体差异的人。','an architectural monstrosity；a concrete monstrosity；call something a monstrosity。','monster 常是怪物或残酷者；monstrosity 常直接指让人嫌恶的物件、建筑或现象。',('The residents called the new car park a concrete monstrosity.','居民把新停车楼叫作一座丑陋的混凝土怪物。'),('The costume was an enormous monstrosity of feathers and wire.','那套服装是个由羽毛和铁丝拼成的巨大怪东西。'),sources=['https://www.etymonline.com/word/monstrosity','https://www.oxfordlearnersdictionaries.com/definition/english/monstrosity']),
E('demonstrate','/ˈdemənstreɪt/','演示；证明；表现出；参加示威','把原本只在嘴上说的内容摆到别人眼前，让人看见怎么做、为什么对或你支持什么。','借自拉丁 demonstratus，接 demonstrare：de- 在这里通常加强语气，monstrare 是显示，不是把怪物去掉。',DEMSTR,'demonstrate a technique 是示范技术；demonstrate that 是证明某事；demonstrate patience 是表现耐心。demonstrate against a decision 则是公开示威反对决定。','demonstrate how；demonstrate that；demonstrate a skill；demonstrate against。','show 很广；demonstrate 更常有清楚展示方法、证据或态度的意味。demonstration 这个名词在英语中更早。',('The instructor demonstrated how to adjust the seat.','教练演示了怎样调节座位。'),('The results demonstrate that the method can work.','结果表明这种方法可以奏效。'),('Residents demonstrated against the closure of the park.','居民举行示威，反对关闭公园。'),sources=['https://www.etymonline.com/word/demonstrate','https://www.oxfordlearnersdictionaries.com/definition/english/demonstrate']),
E('demonstration','/ˌdemənˈstreɪʃən/','演示；证明；表现；示威活动','把技术、事实或诉求公开摆出来的一次活动或展示。','拉丁 demonstratio 经古法语或直接进入英语；名词早于英语 demonstrate，现代拆 demonstrate + -ion 只说明词形对应。',DEMATION,'a cooking demonstration 是烹饪示范；a demonstration of support 是公开表示支持；a peaceful demonstration 是和平示威。核心都在让某种内容变得可见。','give a demonstration；a product demonstration；a demonstration of support；a peaceful demonstration。','presentation 可以只作介绍；demonstration 常亲自展示操作或效果。示威义也不是任何普通人群聚集。',('The shop offers a demonstration of the new coffee machine.','商店提供新咖啡机的操作演示。'),('Hundreds of people joined the peaceful demonstration.','数百人参加了和平示威。'),sources=['https://www.etymonline.com/word/demonstration','https://www.oxfordlearnersdictionaries.com/definition/english/demonstration']),
E('demonstrator','英 /ˈdemənstreɪtə/；美 /ˈdemənstreɪtər/','示威者；演示人员；展示样机','把立场或操作展示出来的人；卖车、卖设备时也可指用来展示的样品。','demonstrate + -or，形成施事名词；较早指讲解、证明者，后来有示威参与者等义。',DEMSTR+[['英语 demonstrate + -or → demonstrator','展示、证明的人 → 示威者；展示用样机']],'a laboratory demonstrator 可带实验课；demonstrators in the square 是广场上的示威者；a demonstrator vehicle 是供展示或试用的车辆。','a laboratory demonstrator；peaceful demonstrators；a demonstrator vehicle。','instructor 强调教学角色；demonstrator 强调操作展示。新闻里看见复数 demonstrators，常先考虑示威者。',('The demonstrator showed us how to use the microscope.','实验指导员向我们演示了显微镜的用法。'),('The demonstrators carried signs through the square.','示威者举着标牌走过广场。'),sources=['https://www.etymonline.com/word/demonstrator','https://www.oxfordlearnersdictionaries.com/definition/english/demonstrator']),
E('demo','英 /ˈdeməʊ/；美 /ˈdemoʊ/','演示；试用版；样带；示范〔动词〕','先给人看一小段、试一部分，让人知道产品或作品大概怎么样。','demonstration 的缩略形式；音乐样带接 demonstration recording 一类说法，动词 demo 再表示做演示。',DEMATION+[['英语 demonstration → demo〔缩略〕','演示、示威 → 演示版、样带等'],['英语 demo〔名词〕→ demo〔动词〕','演示成品 → 展示给人看']],'a software demo 可以是试用版本或现场演示；a music demo 是供别人了解作品的样带，不一定是正式发行。英式口语里 demo 也可说示威。装修语境偶见 demo 缩自 demolition，那是另一条缩略来源。','give a demo；a demo version；record a demo；demo a product。','prototype 是原型，可能很粗糙；demo 重点是拿来展示，展示的东西也可能已经成熟。',('Can you give us a quick demo of the app?','你能给我们简短演示一下这个应用吗？'),('The band recorded a demo in a small studio.','乐队在一间小录音室录了一份样带。'),sources=['https://www.etymonline.com/word/demo','https://www.merriam-webster.com/dictionary/demo','https://www.oxfordlearnersdictionaries.com/definition/english/demo_1']),
E('demonstrable','英 /dɪˈmɒnstrəbəl/；美 /dɪˈmɑːnstrəbəl/','可证明的；能明确显示的','拿得出证据或结果，让别人能够看见，而不只是自己声称如此。','拉丁 demonstrabilis 经法语或直接借入，接 demonstrare；英语形容词也早于 demonstrate，不能只当作现代英语动词新加 -able。',DEMABLE,'a demonstrable benefit 是有证据可见的好处；demonstrable ability 是能实际显示的能力。可以通过数据、实例或操作说明，不限定必须是一条数学证明。','a demonstrable benefit；demonstrable evidence；demonstrable ability。','possible 只是可能；demonstrable 强调能够证明、展示。plausible 则只是看起来说得通。',('The changes produced a demonstrable improvement in response time.','这些改动带来了可以明确看出的响应速度提升。'),('Applicants need demonstrable experience in project management.','申请者需要拿得出证明的项目管理经验。'),sources=['https://www.etymonline.com/word/demonstrable','https://www.oxfordlearnersdictionaries.com/definition/english/demonstrable']),
E('demonstrably','英 /dɪˈmɒnstrəbli/；美 /dɪˈmɑːnstrəbli/','可证明地；有明确证据地','说“这是真的或假的”，同时强调证据能让人确认这一点。','demonstrable + -ly，-able 对应 -ably；不是沿用 demonstrate 的重音。',DEMABLE+[['英语 demonstrable → demonstrably','可以证明的 → 能以证据表明地']],'demonstrably false 是可以证明为假的；demonstrably better 是有可见证据支持更好。它要求比“我觉得”更强的依据，但仍要看作者具体给了什么。','demonstrably false；demonstrably better；demonstrably effective。','obviously 强调说话者认为显然；demonstrably 强调能够拿出证明，不只靠直觉。',('The statement is demonstrably false.','那项说法可以被明确证明是假的。'),('The new layout is demonstrably easier to navigate.','证据表明，新布局更便于浏览和查找。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/demonstrably','https://www.etymonline.com/word/demonstrable']),
E('demonstrative','英 /dɪˈmɒnstrətɪv/；美 /dɪˈmɑːnstrətɪv/','感情外露的；指示的〔语法〕；用于显示、证明的','把内心感情明显表现出来；语法里则像伸出手指，告诉别人“这一个、那一个”。','拉丁 demonstrativus 经法语进入英语，接 demonstrare；不是必须由现代英语 demonstrate 去尾形成。',DEMATIVE,'a demonstrative person 会明显表达亲热、喜悦等感情。this、that 在语法里属于 demonstrative 一类，用来指明所谈对象。两个意义都保留“显示给人看”的方向。','a demonstrative person；demonstrative affection；a demonstrative pronoun。','emotional 是有强烈感情；demonstrative 特别强调把感情表现出来，内心强烈不一定外露。',('He comes from a warm and demonstrative family.','他来自一个温暖、感情表达直接的家庭。'),('In “that book”, “that” is a demonstrative determiner.','在 that book 中，that 是指示限定词。'),sources=['https://www.etymonline.com/word/demonstrative','https://www.oxfordlearnersdictionaries.com/definition/english/demonstrative']),
E('demonstratively','英 /dɪˈmɒnstrətɪvli/；美 /dɪˈmɑːnstrətɪvli/','明显流露感情地；以指示方式〔语法〕','爱、喜悦或亲热直接表现在拥抱、语气和动作上。','demonstrative + -ly；日常主要承接感情外露义，语法中也可说以指示方式使用。',DEMATIVE+[['英语 demonstrative + -ly → demonstratively','感情外露的、指示的 → 以这种方式']],'hug someone demonstratively 可以是热情而明显地拥抱。别与 demonstrably 混淆：前者是表现方式，后者是有证据可证明。','greet demonstratively；embrace demonstratively；used demonstratively。','demonstratively 说表达得外露；demonstrably 说可证明，不能因为拼写相近就互换。',('She greeted her brother demonstratively with a long hug.','她用一个长长的拥抱热情迎接哥哥。'),('The children cheered demonstratively when their teacher returned.','老师回来时，孩子们毫不掩饰地欢呼起来。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/demonstratively','https://www.etymonline.com/word/demonstrative']),
E('undemonstrative','英 /ˌʌndɪˈmɒnstrətɪv/；美 /ˌʌndɪˈmɑːnstrətɪv/','感情不外露的；含蓄的','心里可能很在意，只是不习惯把关心变成明显的表情和动作。','un-“不” + demonstrative；否定的是感情向外表现的方式，不是否定一个人有感情。',DEMATIVE+[['英语 un- + demonstrative → undemonstrative','不 + 感情外露 → 含蓄、不显露情感的']],'an undemonstrative father 可能用实际行动关心孩子，却很少拥抱、说爱。词本身不等于冷酷、没有感情，也不是无法证明的意思。','an undemonstrative person；quiet and undemonstrative；an undemonstrative manner。','unloving 是缺乏爱；undemonstrative 只说明不公开表现。unprovable 才是无法证明。',('He was affectionate but undemonstrative.','他很有感情，只是不善于表现出来。'),('Her undemonstrative manner concealed how pleased she was.','她含蓄的举止掩盖了内心的喜悦。'),sources=['https://www.etymonline.com/word/undemonstrative','https://www.oxfordlearnersdictionaries.com/definition/english/undemonstrative']),
E('muster','英 /ˈmʌstə/；美 /ˈmʌstər/','集合；召集；鼓起、调动；集合检阅〔名词〕','把分散的人、勇气或力气攒起来，让它们能派上用场。','动词经法语 mostrer 接拉丁 monstrare“展示”；名词另接法语 mostre“展示、检阅”。军队集合接受检阅，连接了展示与召集两个意思。',SHOW+[['法语 mostrer → 英语 muster〔动词〕','显示、列队展示 → 召集、鼓起'],['并列：法语 mostre → 英语 muster〔名词〕','展示、检阅 → 集合、人员名册等']],'muster the courage 是鼓起勇气；muster support 是争取、集结支持。pass muster 原与检阅合格有关，今天说某物达到要求、过得了关。','muster the courage；muster support；muster the troops；pass muster。','gather 很广；muster 常强调为了行动把可用的人力、力量或精神调动起来。',('She mustered the courage to ask for help.','她鼓起勇气请求帮助。'),('The first draft did not pass muster with the editor.','初稿没有通过编辑的审查。'),sources=['https://www.etymonline.com/word/muster','https://www.oxfordlearnersdictionaries.com/definition/english/muster_1']),
E('remonstrate','英 /ˈremənstreɪt/；美 /rɪˈmɑːnstreɪt/','抗议；规劝；提出强烈异议','不只说“我不高兴”，还把为什么不该这样做的理由提出来。','接中世纪拉丁 remonstratus，或从英语 remonstration 反构；re- 在该古典构词中可能加强显示，不简单等于再次示威。',REM+[['两种可能近源：拉丁语 remonstratus；或英语 remonstration 反构','显示清楚、提出理由'],['英语 remonstrate','从说明、指出发展为规劝、抗议']],'常用 remonstrate with someone about something，较正式、书面。可以是一对一规劝，不必是走上街头的集体示威。','remonstrate with；remonstrate about；remonstrate against。','demonstrate 的示威义常是公开集体行动；remonstrate 更侧重当面或正式表达反对理由。',('She remonstrated with the driver about his speed.','她就车速问题向司机提出了严正劝告。'),('The residents remonstrated against the sudden change of plan.','居民对计划突然改变提出了抗议。'),sources=['https://www.etymonline.com/word/remonstrate','https://www.oxfordlearnersdictionaries.com/definition/english/remonstrate']),
E('remonstrance','英 /rɪˈmɒnstrəns/；美 /rɪˈmɑːnstrəns/','抗议；规劝；正式异议','把不赞成的理由明确说出，可能是一段话、一封信或正式声明。','古法语 remonstrance 或中世纪拉丁 remonstrantia 借入，接 remonstrare；英语名词早于 remonstrate，不能只按后缀推成后造。',REM+[['中世纪拉丁语 remonstrantia → 古法语 remonstrance → 英语 remonstrance','说明、请求 → 正式抗议、规劝']],'a letter of remonstrance 是抗议信；a gesture of remonstrance 是表示异议的动作。语体正式，普通聊天常用 protest 或 objection。','a letter of remonstrance；in remonstrance；ignore someone’s remonstrances。','complaint 可以只是诉苦；remonstrance 常包含劝阻、纠正或正式反对的意味。',('They sent a letter of remonstrance to the committee.','他们向委员会寄去了一封抗议信。'),('He raised a hand in mild remonstrance.','他举起一只手，温和地表示异议。'),sources=['https://www.etymonline.com/word/remonstrance','https://www.oxfordlearnersdictionaries.com/definition/english/remonstrance']),
E('counterdemonstration','英 /ˌkaʊntəˌdemənˈstreɪʃən/；美 /ˌkaʊntərˌdemənˈstreɪʃən/','反示威；回应另一场示威的对立集会','一群人公开表达一种立场，另一群人组织行动表达相反立场。','counter-“对抗、回应” + demonstration；英语现代复合词，可连写，本页保留连写形式。',DEMATION+[['英语 counter- + demonstration → counterdemonstration','对抗 + 示威 → 与另一场示威相对的集会']],'词中 counter- 说明两场示威的立场关系，不表示哪一方合法或正确，也不必发生暴力。两场活动可以在不同地点或时间举行。','organise a counterdemonstration；a peaceful counterdemonstration；hold a counterdemonstration。','demonstration 是一般示威；counterdemonstration 特别针对另一场示威或其主张。',('A peaceful counterdemonstration took place across the square.','广场另一边举行了一场和平的反示威。'),('The organisers announced a counterdemonstration for the following day.','组织者宣布将在第二天举行反示威。'),sources=['https://www.merriam-webster.com/dictionary/counterdemonstration','https://en.wiktionary.org/wiki/counterdemonstration#English']),
E('counterdemonstrator','英 /ˌkaʊntəˈdemənstreɪtə/；美 /ˌkaʊntərˈdemənstreɪtər/','反示威者；参加对立集会的人','在回应另一场示威的活动里，表达相反立场的参与者。','counter- + demonstrator；与 counterdemonstration 对应，但构词上可直接给人物名词 demonstrator 加 counter-。',DEMSTR+[['英语 demonstrator → counterdemonstrator','示威者 → 对另一场示威表达反对的参与者']],'a counterdemonstrator 是一个人，不是整场活动。这个角色名称只说明其立场与原示威对立，不应从词本身推断其行为或动机。','counterdemonstrators gathered；a group of counterdemonstrators；peaceful counterdemonstrators。','demonstrator 包括所有示威参与者；counterdemonstrator 是在两场相对活动中的特定角色。',('The counterdemonstrators held signs expressing the opposite view.','反示威者举着标牌，表达相反观点。'),('A reporter interviewed one demonstrator and one counterdemonstrator.','记者采访了一名示威者和一名反示威者。'),sources=['https://www.merriam-webster.com/dictionary/counterdemonstrator']),
]
C=[['拉丁语 circus','圆环、环形场地；与希腊语 kirkos 的具体关系有不同分析']]
CL=C+[['拉丁语 circulus〔指小形式〕','小圈、圆环']]
CIRCLE=CL+[['古法语 cercle → 英语 circle','圆、圆圈；同一兴趣或关系圈中的人']]
CIRCULAR=CL+[['拉丁语 circularis → 法语 circuler 等 → 英语 circular','圆形的；后来指供传阅的、论证绕回原点的']]
CIRCARE=CL+[['拉丁语 circulare / circulatus','使成圆、循环处理']]
CIRCULATE=CIRCARE+[['英语 circulate','早期循环处理物质 → 流动、传播、在人群间走动']]
CIRCULATION=CIRCARE+[['拉丁语 circulatio → 英语 circulation','循环过程 → 血液、空气、信息、出版物等的流通']]
ENCIRCLE=CIRCLE+[['英语 en- + circle → encircle','使处于圈内 → 环绕、包围']]
W += [
E('circle','英 /ˈsɜːkəl/；美 /ˈsɜːrkəl/','圆；圈子；环绕、盘旋；圈出〔动词〕','一条线绕一圈回到原处；人围在共同兴趣或关系周围，也形成一个“圈”。','经古法语 cercle 接拉丁 circulus，是 circus“圆环”的指小形式；动词后来由英语名词形成。',CIRCLE+[['英语 circle〔名词〕→ circle〔动词〕','圆圈 → 绕圈、圈出']],'几何上圆周各点到圆心距离相同；a circle of friends 是朋友圈。circle the answer 是把答案圈出来；birds circle overhead 是鸟在头顶盘旋。come full circle 则说绕了一圈又回到起点或类似状态。','draw a circle；a circle of friends；circle the answer；come full circle。','round 可以形容圆，也有其他词性；circle 是圆这个形状或绕圈动作。social circle 不是必须围坐成真实圆形。',('Draw a circle around the correct answer.','在正确答案周围画一个圈。'),('She has a small circle of close friends.','她有一个不大的密友圈。'),('A bird circled above the field.','一只鸟在田野上空盘旋。'),sources=['https://www.etymonline.com/word/circle','https://www.oxfordlearnersdictionaries.com/definition/english/circle_1']),
E('circus','英 /ˈsɜːkəs/；美 /ˈsɜːrkəs/','马戏团；马戏演出；闹哄哄的场面；圆形广场〔地名〕','人们围着表演场地看节目；引申时，一件事热闹混乱得像整场表演。','借自拉丁 circus“环形场地”，英语早期用于古罗马竞赛场，后来扩展到现代马戏及表演团体。',C+[['英语 circus','古罗马竞赛场 → 马戏场、马戏团；闹剧般场面']],'go to the circus 是去看马戏；a media circus 是媒体蜂拥、关注喧闹的场面。伦敦 Piccadilly Circus 的 Circus 是地名里的广场、道路交汇处，并不是马戏团所在地这一字面保证。','a circus performer；go to the circus；a media circus。','circle 是形状；circus 是从环形场地发展出的活动、机构名称，古罗马竞赛场也常呈长椭圆形。',('The children watched acrobats at the circus.','孩子们在马戏演出中观看杂技演员表演。'),('The trial turned into a media circus.','那场审判变成了媒体蜂拥围观的喧闹场面。'),sources=['https://www.etymonline.com/word/circus','https://www.oxfordlearnersdictionaries.com/definition/english/circus']),
E('circular','英 /ˈsɜːkjələ/；美 /ˈsɜːrkjələr/','圆形的；循环的；循环论证的；通告、传单〔名词〕','形状绕一圈；论证若绕回原来尚未证明的结论，就成了原地打转。','拉丁 circularis 经法语进入英语；现代可联系 circle + -ar，但形容词有独立借入路线。名词通告来自 circular letter 一类说法。',CIRCULAR+[['英语 circular letter → circular〔通告名词〕','分发给同一圈人的信 → 供传阅的通知']],'a circular table 是圆桌；a circular route 绕行后回到起点。circular reasoning 用所要证明的内容支持它自己。a circular 则是发给许多人看的通知，不必印在圆纸上。','a circular table；a circular route；circular reasoning；issue a circular。','cyclical 常说事情按周期重现；circular 更强调圆形、回绕关系，论证义通常指出问题。',('The hall has a circular window above the entrance.','大厅入口上方有一扇圆窗。'),('The argument is circular because its conclusion is already assumed in the premise.','这个论证是循环的，因为前提已经假定了结论成立。'),('The office sent a circular to all members.','办公室向全体成员发出了一份通知。'),sources=['https://www.etymonline.com/word/circular','https://www.oxfordlearnersdictionaries.com/definition/english/circular_1']),
E('circularity','英 /ˌsɜːkjəˈlærəti/；美 /ˌsɜːrkjəˈlærəti/','循环性；循环论证；圆形特征；资源循环利用','可以说形状像圆，也可以说理由绕回来，或材料用过以后再次进入使用环节。','circular + -ity；从圆形、回绕的形容词派生表示性质的名词。',CIRCULAR+[['英语 circular + -ity → circularity','圆形、回绕的 → 圆形性质、循环关系等']],'the circularity of an argument 指论证绕回自身；材料利用中的 circularity 则强调重复使用、修复、回收等循环安排。前者常是批评，后者通常是设计目标，不能一律翻成“逻辑错误”。','circularity in reasoning；material circularity；the circularity of a shape。','circulation 是流动或流通过程；circularity 更偏循环结构、性质或循环利用程度。',('The reviewer pointed out the circularity in the argument.','评审指出了论证中的循环问题。'),('The design aims to improve material circularity through reuse and repair.','设计希望通过再利用和维修提高材料的循环利用程度。'),sources=['https://www.etymonline.com/word/circularity','https://www.oxfordlearnersdictionaries.com/definition/english/circularity']),
E('circulate','英 /ˈsɜːkjəleɪt/；美 /ˈsɜːrkjəleɪt/','循环流动；传播；传阅；在人群中走动','东西不一直停在一处，而是在系统或人群中不断转到别处。','接拉丁 circulatus、circulare，来自 circulus“小圈”；英语早期有循环处理物质的技术义，后扩展到血液、消息和人际流动。',CIRCULATE,'blood circulates 是血液循环；circulate a document 是分发传阅文件；rumours circulate 是传言四处传播。聚会上 circulate 还可说走到不同人群中交谈。','circulate freely；circulate a document；rumours circulate；circulate among guests。','rotate 是绕轴转动；circulate 更强调在各处或各人之间流动，不要求每个对象画出几何圆。',('The fan helps air circulate through the room.','风扇帮助空气在房间里流动。'),('Please circulate the revised agenda before the meeting.','请在会议前把修订后的议程发给大家传阅。'),('She circulated among the guests, introducing people to one another.','她在人群中走动，为宾客们相互介绍。'),sources=['https://www.etymonline.com/word/circulate','https://www.oxfordlearnersdictionaries.com/definition/english/circulate']),
E('circulation','英 /ˌsɜːkjəˈleɪʃən/；美 /ˌsɜːrkjəˈleɪʃən/','循环；流通；传播；发行量','看一件东西怎样在一个系统里流动，或总共有多少份在读者间流传。','拉丁 circulatio 进入英语，接 circulare；名词早于常见动词 circulate，不能只当成英语动词后加 -ion。',CIRCULATION,'blood circulation 是血液循环；money in circulation 是流通中的货币；a newspaper’s circulation 是发行量，并不等于每份报纸实际被多少个人阅读。out of circulation 可说停止流通，也可口语说暂不参加社交。','blood circulation；air circulation；in circulation；a daily circulation。','distribution 强调分配、送达；circulation 还强调在系统中的流转，报刊语境常指发行数量。',('The diagram shows the circulation of blood through the heart.','示意图展示了血液经过心脏的循环过程。'),('These old coins are no longer in circulation.','这些旧硬币已不再流通。'),('The newspaper reported a decline in circulation.','这家报纸报告称发行量有所下降。'),sources=['https://www.etymonline.com/word/circulation','https://www.oxfordlearnersdictionaries.com/definition/english/circulation']),
E('circulatory','英 /ˌsɜːkjəˈleɪtəri/；美 /ˈsɜːrkjələtɔːri/','循环的；血液循环系统的','说明所谈的器官、过程或问题属于血液在身体里运送、流动这一套系统。','经法语 circulatoire 或直接接拉丁 circulatorius，源于 circulare 一系；现代对应 circulation，但不是仅由英语名词换尾。',CIRCARE+[['拉丁语 circulatorius → 法语 circulatoire / 英语 circulatory','与循环有关 → 血液循环的']],'the circulatory system 通常指心脏、血管等组成的血液循环体系。词也有广义循环相关用法，但日常学习最常遇到这个生物学搭配。英美常用重音明显不同。','the circulatory system；circulatory problems；circulatory function。','respiratory 说呼吸系统；circulatory 说循环系统，二者合作却不是同一套名称。',('The lesson explains how the circulatory system transports oxygen.','这一课解释循环系统怎样运输氧。'),('The diagram labels the main parts of the circulatory system.','图中标出了循环系统的主要组成部分。'),sources=['https://www.etymonline.com/word/circulatory','https://www.oxfordlearnersdictionaries.com/definition/english/circulatory']),
E('encircle','英 /ɪnˈsɜːkəl/；美 /ɪnˈsɜːrkəl/','环绕；围住；包围','四周形成一圈，把某个东西放在圈里。','en-“使处于、放入” + circle；中古英语已按这一方式构成动词。',ENCIRCLE,'trees encircle a lake 是树木围湖一圈；arms encircle someone 是用双臂环抱。军事场景也可说部队形成包围，但并不要求边界是精确的圆。','encircle a town；be encircled by；encircle with one’s arms。','surround 广泛表示四周围着；encircle 更容易让人想象环形围合或完整包围。',('A low stone wall encircles the garden.','一道低石墙环绕着花园。'),('She encircled the child with her arms.','她用双臂把孩子环抱住。'),sources=['https://www.etymonline.com/word/encircle','https://www.oxfordlearnersdictionaries.com/definition/english/encircle']),
E('encirclement','英 /ɪnˈsɜːkəlmənt/；美 /ɪnˈsɜːrkəlmənt/','包围；环绕；被围住的状态','把“周围都被围上了”这件事作为一个过程或局面来谈。','encircle + -ment；表示环绕的行动或形成的状态。',ENCIRCLE+[['英语 encircle + -ment → encirclement','环绕、包围 → 包围行动或局面']],'军事历史中的 encirclement 常说明部队被围住；地理描写也可说群山环抱。它不自动等于已经被攻占，更不是所有孤立状态都形成了实际包围。','the encirclement of；escape encirclement；a ring of encirclement。','isolation 是孤立，可能因为缺少联系；encirclement 特别强调周围被围住的布局。',('The chapter describes the encirclement of the city.','这一章描述了城市被包围的过程。'),('The valley’s encirclement by mountains gives it a sheltered feel.','山峦对山谷的环抱让这里显得十分避风安稳。'),sources=['https://www.etymonline.com/word/encirclement','https://www.oxfordlearnersdictionaries.com/definition/english/encirclement']),
E('semicircle','英 /ˈsemisɜːkəl/；美 /ˈsemisɜːrkəl/','半圆；半圆形排列','把一个圆分成两半，其中一半；人或椅子也可以沿这个形状排开。','semi-“半” + circle，或直接联系拉丁 semicirculus；两种近源分析都指半个圆，不能只凭字形断定英语现造。',CL+[['拉丁语 semi- + circulus → semicirculus；或英语 semi- + circle','半 + 圆 → 半圆'],['英语 semicircle','半圆；半圆形排列']],'sit in a semicircle 是围成半圆坐。几何语境可依描述指半圆弧或半圆区域，日常场景主要关注半圈的外形。','in a semicircle；form a semicircle；draw a semicircle。','circle 是完整一圈；semicircle 只有一半。hemisphere 是半球，属于三维空间。',('The children sat in a semicircle around the storyteller.','孩子们围着讲故事的人坐成半圆。'),('Draw a semicircle above the straight line.','在直线上方画一个半圆。'),sources=['https://www.etymonline.com/word/semicircle','https://www.oxfordlearnersdictionaries.com/definition/english/semicircle']),
E('semicircular','英 /ˌsemiˈsɜːkjələ/；美 /ˌsemiˈsɜːrkjələr/','半圆形的','拿来修饰一个外形像半圈的窗、拱、座位或结构。','现代可看 semi- + circular；英语较早形态接中世纪拉丁 semicirculus 与 -ar，不把它一定排在英语名词 semicircle 之后。',CL+[['中世纪拉丁语 semicirculus 与 -ar → 中古英语 semicirculer','半圆 → 半圆形的'],['英语 semicircular','半圆形的；现代可对应 semi- + circular']],'a semicircular window 是半圆窗；a semicircular arrangement 是半圆布局。内耳的 semicircular canals 是常见专门搭配，名称来自弯曲的环管形态。','a semicircular arch；a semicircular window；a semicircular arrangement。','semicircle 是名词；semicircular 是描述形状的形容词。circular 则没有“半”的限制。',('A semicircular window lets light into the attic.','一扇半圆窗让光线照进阁楼。'),('The chairs were placed in a semicircular arrangement.','椅子被摆成了半圆形。'),sources=['https://www.etymonline.com/word/semicircular','https://www.oxfordlearnersdictionaries.com/definition/english/semicircular']),
E('circlet','英 /ˈsɜːklət/；美 /ˈsɜːrklət/','小环；环形头饰','一个细小的环，文学里尤其容易是戴在头上的金属圈或花环。','借自法语 cerclet，是 cercle 的指小形式；现代可与 circle + -et 对照，但小词形式先在法语中形成。',CL+[['法语 cercle → 指小形式 cerclet → 英语 circlet','圆圈 → 小环；环形头饰']],'a silver circlet 可指银质头环；a circlet of flowers 是花朵围成的环。比普通 ring 更有小巧、装饰性和文学描写的语感。','a silver circlet；a circlet of flowers；wear a circlet。','crown 常有王冠或冠冕含义；circlet 只是环状头饰，不必代表王权。',('She wore a simple silver circlet in her hair.','她在头发上戴着一枚朴素的银色头环。'),('The children made a circlet of daisies.','孩子们用雏菊做了一个小花环。'),sources=['https://www.etymonline.com/word/circlet','https://www.oxfordlearnersdictionaries.com/definition/english/circlet']),
]
DEFERRED={'Premonstratensian':'专门宗教团体称谓，按最新冷门词范围暂缓。','grandioso':'意大利音乐表情术语，暂缓。','grandific':'古旧罕用词。','grandiloquous':'罕用形容词，先学习 grandiloquent。','grandity':'古旧罕用名词。','monstrance':'专门宗教礼器名，暂缓。','remonstrant':'较专门历史宗教称谓或低频一般派生，暂缓。','demonstrant':'低频人物名称，先学 demonstrator。','demonstratory':'低频形容词，先学 demonstrative、demonstrable。','indemonstrable':'低频透明否定形式，先学 demonstrable。','monstration':'罕用展示名词，暂缓。','premonstrate':'古旧罕用动词。','premonstration':'古旧罕用名词。','premonstrator':'极罕用人物名词。','remonstration':'低频抗议名词，先学 remonstrance；仅在词源中说明其早期作用。','remonstrative':'低频形容词，暂缓。','circulator':'较专门循环器或传播者名称，暂缓。','circularly':'低频透明副词，先学 circular。'}
GRAND_ROOT=dict(id='C0501',meaning='大、重要、有气派；隔一代的亲属',core='grand 不只是大，还可以是隆重、有分量。放进亲属名称里时，它标记隔一代，不是说这个人更高贵或身材更大。',image='grandis 大、重要 → grand 气派；grand- + father / child → 祖父辈、孙辈；grandeur 壮丽；grandiose 夸张宏大；grandstand 看台 → 向观众作秀。',intro='主线是拉丁 grandis，经法语等进入英语；更早来源未定。家庭称谓中 grandmother、grandfather 可能仿法语模式，英语不区分父系和母系。granny 多被解释为较早 grandam、grannam 一系的缩略，不能把每个短称都写成从 grandmother 直接剪出来。',forms='grand- 在亲属名称里上下都可隔一代：grandparent 向上，grandchild 向下。grandchild 的复数是 grandchildren。grandee 经西班牙语，grandiose 经意大利语、法语，grandiloquent 的近源还有借入与反构两类解释。',branches=[['宏大、气派与浮夸','grand, grandly, grandeur, grandiose, grandiosity, grandee, grandiloquent'],['祖辈与孙辈','grandfather, grandmother, grandparent, grandchild, grandson, granddaughter, grandkid'],['亲昵称呼','grandma, grandpa, granddad, granddaddy, granny'],['看台与作秀','grandstand, grandstanding']],contrasts='grand 常赞气派，grandiose 常批不现实。grandfather 与 grandmother 不区分外祖父母；grandkid 也不区分内外孙。grandstanding 是给观众看的姿态，不是普通站立。',practice='用 maternal、paternal 说清祖辈是哪一边；用 grand、grandiose、grandiloquent 分别评价建筑、夸张计划和浮夸讲话。',words=[w for w in ASSIGN['roots'][65]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][65]['family'] if w in DEFERRED})
MONSTRA_ROOT=dict(id='C0761',meaning='显示、指明；征兆、怪物与公开表达',core='把某件事摆到别人眼前，让人注意到。古人把异常现象看作警示，形成怪物支线；展示操作、证据和诉求，则通向证明、演示与示威。',image='monere 提醒 → monstrum 征兆 → monster；monstrare 显示 → demonstrate、demonstration；军队列队展示 → muster；提出反对理由 → remonstrate。',intro='monster 与 demonstrate 看起来很不相像，却都接到提醒、显示这条古典支线。monstrum 的旧义包含古人对异常现象的信念，本页不把这些观念当作事实。demonstration、demonstrable、demonstrative 都有较早独立借入历史，不能只用英语 demonstrate 加后缀来画祖先链。',forms='de- 在 demonstrare 中通常起加强作用，不是去掉怪物；re- 在 remonstrare 中也不一定只是重复。demonstrator 是人，demonstration 是活动或证明，demonstrable 是能证明，demonstrative 的日常义则是感情外露。',branches=[['怪物、巨大与骇人','monster, monstrous, monstrously, monstrosity'],['展示与证明','demonstrate, demonstration, demonstrator, demo, demonstrable, demonstrably'],['情感是否表现出来','demonstrative, demonstratively, undemonstrative'],['集合、规劝与对立表达','muster, remonstrate, remonstrance, counterdemonstration, counterdemonstrator']],contrasts='demonstrably 强调可证明，demonstratively 强调表达方式，拼写近不等于语义近。undemonstrative 不等于没有爱。remonstrate 可是一对一正式劝阻，不必集体示威。',practice='分别用 demonstrate、demonstrable、demonstrative 描述示范操作、有证据的改善、感情外露的人。解释 muster the courage 为什么能从集合检阅发展而来。',words=[w for w in ASSIGN['roots'][66]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][66]['family'] if w in DEFERRED})
CIRC_ROOT=dict(id='C0221',meaning='圆环、小圈；环绕、循环与流通',core='从绕一圈的形状出发，既能看见圆桌、头环，也能理解血液流动、文件传阅和同一社交圈。',image='circus 圆环、场地 → circus；circulus 小圆环 → circle、circular；circulare 循环 → circulate、circulation；en- 放进圈中 → encircle；semi- 半 → semicircle。',intro='这组从拉丁 circus、circulus 出发；与希腊 kirkos 的更早具体关系有不同分析，不强行画单一路线。circle、circular、circulation、circulatory 各有古典或法语借入历史，不能全部写成英语 circle 现加后缀。circlet 的指小形式先在法语形成。',forms='circ- 是圆环支线，circul- 连接拉丁 circulus。-ar 描述性质，-ation 常名词化过程，-ory 表相关。semicircular 在英语里的记录早于 semicircle，现代可拆 semi- + circular，不代表历史上必须由英语 semicircle 再派生。',branches=[['形状、圈子与表演场','circle, circus, circlet, circular'],['半圈与包围','semicircle, semicircular, encircle, encirclement'],['流动、发行与循环系统','circulate, circulation, circulatory'],['回绕结构与循环利用','circularity']],contrasts='circulation 是流动过程或发行量，circularity 是循环性质、循环论证或循环利用。circular 通告不是圆纸。circulate 不同于绕轴 rotate，消息传开也不必真的回到原处。',practice='把 circle 用于图形和朋友关系；用 circulation 分别说血液、货币和报纸；解释 circular reasoning 为什么是在原地绕圈。',words=[w for w in ASSIGN['roots'][67]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][67]['family'] if w in DEFERRED})
MONSTRA_ROOT['exclude']['Premonstratensian']=DEFERRED['Premonstratensian']
roots=[GRAND_ROOT,MONSTRA_ROOT,CIRC_ROOT]
expected={w for r in ASSIGN['roots'][65:68] for w in r['family'] if w in set(ASSIGN['owned_words']) and w not in DEFERRED}
assert {w['word'] for w in W}==expected,({w['word'] for w in W}-expected,expected-{w['word'] for w in W})
