for kind,data in [('roots',roots),('words',W)]: (OUT/f'{kind}_batch200_st_21.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
p=Path('.cache/batch200/rewrite_st_progress.json');progress=json.loads(p.read_text())
